import [printf] from "std/c.bpl";

# Define an error type
struct DivisionError {
    message: string,
    dividend: int,
    divisor: int,
}

frame divide(a: int, b: int) ret int {
    if (b == 0) {
        throw DivisionError {
            message: "Cannot divide by zero",
            dividend: a,
            divisor: b
        };
    }
    return a / b;
}

frame main() ret int {
    # Try a successful division
    try {
        local result: int = divide(10, 2);
        printf("10 / 2 = %d\n", result);
    } catch (e: DivisionError) {
        printf("Error: %s\n", e.message);
    }

    # Try a division by zero
    try {
        printf("Trying 10 / 0...\n");
        local result: int = divide(10, 0);
        printf("Result: %d\n", result);  # Never reached
    } catch (e: DivisionError) {
        printf("Caught error: %s\n", e.message);
        printf("Tried: %d / %d\n", e.dividend, e.divisor);
    }

    printf("\nProgram continues after error handling!\n");

    return 0;
}

import [printf] from "std/c.bpl";

# Different error types
struct FileNotFoundError {
    filename: string,
}

struct PermissionError {
    filename: string,
    required: string,
}

struct NetworkError {
    host: string,
    code: int,
}

frame simulateFileOperation(op: int) {
    if (op == 1) {
        throw FileNotFoundError { filename: "data.txt" };
    }
    if (op == 2) {
        throw PermissionError { filename: "secret.txt", required: "read" };
    }
    if (op == 3) {
        throw NetworkError { host: "api.example.com", code: 503 };
    }
    printf("Operation successful!\n");
}

frame main() ret int {
    # Test different errors
    loop (local i: int = 0; i <= 3; i = i + 1) {
        printf("--- Operation %d ---\n", i);

        try {
            simulateFileOperation(i);
        } catch (e: FileNotFoundError) {
            printf("File not found: %s\n", e.filename);
        } catch (e: PermissionError) {
            printf("Permission denied: need '%s' for %s\n", e.required, e.filename);
        } catch (e: NetworkError) {
            printf("Network error: %s (code %d)\n", e.host, e.code);
        }

        printf("\n");
    }

    return 0;
}

import [printf] from "std/c.bpl";

struct KnownError {
    code: int,
}

frame riskyOperation(op: int) {
    if (op == 1) {
        throw KnownError { code: 42 };
    }
    if (op == 2) {
        throw "Something unexpected happened";  # Throw a string!
    }
    if (op == 3) {
        throw 999;  # Throw an integer!
    }
    printf("Success!\n");
}

frame main() ret int {
    loop (local i: int = 0; i <= 3; i = i + 1) {
        printf("--- Test %d ---\n", i);

        try {
            riskyOperation(i);
        } catch (e: KnownError) {
            printf("Known error with code: %d\n", e.code);
        } catch {
            printf("Unknown error occurred!\n");
            # Can't access the error value here
        }

        printf("\n");
    }

    return 0;
}

import [printf] from "std/c.bpl";

struct ValidationError {
    field: string,
    message: string,
}

frame validateAge(age: int) {
    if (age < 0) {
        throw ValidationError {
            field: "age",
            message: "Age cannot be negative"
        };
    }
    if (age > 150) {
        throw ValidationError {
            field: "age",
            message: "Age seems unrealistic"
        };
    }
}

frame processUser(name: string, age: int) {
    printf("Processing user: %s, age %d\n", name, age);

    # This might throw - we let it propagate up
    validateAge(age);

    printf("User %s validated successfully!\n", name);
}

frame main() ret int {
    # Error propagates from validateAge through processUser to main
    try {
        processUser("Alice", 25);
        processUser("Bob", -5);     # This will throw
        processUser("Carol", 30);   # Never reached
    } catch (e: ValidationError) {
        printf("Validation failed!\n");
        printf("Field: %s\n", e.field);
        printf("Error: %s\n", e.message);
    }

    printf("\n--- Second batch ---\n");

    try {
        processUser("Dave", 200);   # Too old
    } catch (e: ValidationError) {
        printf("Error: %s\n", e.message);
    }

    return 0;
}

import [printf], [malloc], [free] from "std/c.bpl";

struct Resource {
    name: string,
    data: *void,

    frame acquire(name: string) ret Resource {
        printf("Acquiring resource: %s\n", name);
        return Resource {
            name: name,
            data: malloc(100)
        };
    }

    frame release(this: *Resource) {
        printf("Releasing resource: %s\n", this.name);
        if (this.data != nullptr) {
            free(this.data);
            this.data = nullptr;
        }
    }
}

frame riskyWork() {
    throw "Something went wrong!";
}

frame doWork() {
    local res: Resource = Resource.acquire("Database");

    # defer ensures cleanup happens even if exception is thrown
    defer {
        res.release();
    }

    printf("Doing work...\n");
    riskyWork();  # This throws!
    printf("Work complete!\n");  # Never reached
}

frame main() ret int {
    try {
        doWork();
    } catch (e: string) {
        printf("Error caught in main: %s\n", e);
    }

    printf("\nProgram finished cleanly!\n");

    return 0;
}

