import [printf] from "std/c.bpl";

struct IndexOutOfBoundsError {
    index: int,
    size: int,
}

frame safeGet(arr: *int, size: int, index: int) ret int {
    if (index < 0 || index >= size) {
        throw IndexOutOfBoundsError {
            index: index,
            size: size
        };
    }
    return *(arr + index);
}

frame main() ret int {
    local data: int[5] = [10, 20, 30, 40, 50];

    try {
        printf("data[2] = %d\n", safeGet(&data[0], 5, 2));
        printf("data[10] = %d\n", safeGet(&data[0], 5, 10));
    } catch (e: IndexOutOfBoundsError) {
        printf("Error: index %d out of bounds (size %d)\n", e.index, e.size);
    }

    return 0;
}
